const { Pool } = require('pg');
const { createClient } = require('@clickhouse/client');

async function main() {
  const pg = new Pool({ connectionString: process.env.POSTGRES_URL });
  const ch = createClient({
    url: process.env.CLICKHOUSE_URL,
    clickhouse_settings: { async_insert: 0 },
  });

  // Create database and table in ClickHouse
  await ch.exec({ query: 'CREATE DATABASE IF NOT EXISTS analytics' });

  await ch.exec({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.product_events (
        event_id    String,
        event_ts    DateTime64(3, 'UTC'),
        user_id     String,
        product_id  String,
        event_type  LowCardinality(String),
        price       Nullable(Float64)
      )
      ENGINE = MergeTree()
      ORDER BY (event_ts, product_id, event_type)
    `,
  });

  // Truncate for idempotency
  await ch.exec({ query: 'TRUNCATE TABLE analytics.product_events' });

  // Read from Postgres
  const { rows } = await pg.query(`
    SELECT event_id, event_ts, user_id, product_id, event_type,
           (properties->>'price')::float AS price
    FROM raw.product_events
    ORDER BY event_ts
  `);

  console.log(`Ingesting ${rows.length} events...`);

  const values = rows.map(r => ({
    event_id: r.event_id,
    event_ts: new Date(r.event_ts).toISOString().replace('T', ' ').replace('Z', ''),
    user_id: r.user_id,
    product_id: r.product_id,
    event_type: r.event_type,
    price: r.price ?? null,
  }));

  await ch.insert({
    table: 'analytics.product_events',
    values,
    format: 'JSONEachRow',
  });

  // Build materialized aggregation tables
  await ch.exec({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.top_products (
        product_id  String,
        views       UInt64,
        carts       UInt64,
        purchases   UInt64,
        revenue     Float64
      )
      ENGINE = MergeTree()
      ORDER BY product_id
    `,
  });

  await ch.exec({ query: 'TRUNCATE TABLE analytics.top_products' });
  await ch.exec({
    query: `
      INSERT INTO analytics.top_products
      SELECT
        product_id,
        countIf(event_type = 'view')     AS views,
        countIf(event_type = 'cart')     AS carts,
        countIf(event_type = 'purchase') AS purchases,
        sumIf(price, event_type = 'purchase' AND price IS NOT NULL) AS revenue
      FROM analytics.product_events
      GROUP BY product_id
    `,
  });

  await ch.exec({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.funnel (
        step    String,
        cnt     UInt64
      )
      ENGINE = MergeTree()
      ORDER BY step
    `,
  });

  await ch.exec({ query: 'TRUNCATE TABLE analytics.funnel' });
  await ch.exec({
    query: `
      INSERT INTO analytics.funnel
      SELECT event_type AS step, count() AS cnt
      FROM analytics.product_events
      GROUP BY event_type
    `,
  });

  await ch.exec({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.hourly_activity (
        hour        DateTime,
        event_type  LowCardinality(String),
        cnt         UInt64
      )
      ENGINE = MergeTree()
      ORDER BY (hour, event_type)
    `,
  });

  await ch.exec({ query: 'TRUNCATE TABLE analytics.hourly_activity' });
  await ch.exec({
    query: `
      INSERT INTO analytics.hourly_activity
      SELECT
        toStartOfHour(event_ts) AS hour,
        event_type,
        count() AS cnt
      FROM analytics.product_events
      GROUP BY hour, event_type
    `,
  });

  // Verify
  const result = await ch.query({
    query: 'SELECT count() AS n FROM analytics.product_events',
    format: 'JSONEachRow',
  });
  const [{ n }] = await result.json();
  console.log(`Done. ClickHouse has ${n} events.`);

  await pg.end();
  await ch.close();
}

main().catch(err => { console.error(err); process.exit(1); });

