const http = require('http');
const { createClient } = require('@clickhouse/client');

const ch = createClient({ url: process.env.CLICKHOUSE_URL });
const PORT = 3000;

async function query(sql) {
  const result = await ch.query({ query: sql, format: 'JSONEachRow' });
  return result.json();
}

function send(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

const routes = {
  '/api/top-products': async () => {
    const rows = await query(`
      SELECT product_id, views, carts, purchases, revenue
      FROM analytics.top_products
      ORDER BY revenue DESC, purchases DESC
    `);
    return rows.map(r => ({
      product_id: r.product_id,
      views: Number(r.views),
      carts: Number(r.carts),
      purchases: Number(r.purchases),
      revenue: Number(r.revenue),
    }));
  },

  '/api/funnel': async () => {
    const rows = await query(`
      SELECT step, cnt FROM analytics.funnel
    `);
    const map = Object.fromEntries(rows.map(r => [r.step, Number(r.cnt)]));
    return [
      { step: 'view',     count: map['view']     ?? 0 },
      { step: 'cart',     count: map['cart']     ?? 0 },
      { step: 'purchase', count: map['purchase'] ?? 0 },
    ];
  },

  '/api/hourly': async () => {
    const rows = await query(`
      SELECT hour, event_type, cnt
      FROM analytics.hourly_activity
      ORDER BY hour, event_type
    `);
    return rows.map(r => ({
      hour: r.hour,
      event_type: r.event_type,
      count: Number(r.cnt),
    }));
  },
};

const server = http.createServer(async (req, res) => {
  const handler = routes[req.url];
  if (!handler) {
    return send(res, 404, { error: 'Not found', path: req.url });
  }
  try {
    const data = await handler();
    send(res, 200, data);
  } catch (err) {
    console.error(err);
    send(res, 500, { error: 'Internal server error' });
  }
});

server.listen(PORT, () => {
  console.log(`API server listening on port ${PORT}`);
});

